import React, { useEffect, useRef, ReactNode, Children, isValidElement } from 'react';
import { motion, useAnimation } from 'framer-motion';

interface AnimatedListProps {
  children: ReactNode;
  className?: string;
  staggerDelay?: number; // ms
  randomVariation?: number; // ms
  onComplete?: () => void;
  component?: 'ul' | 'ol' | 'div';
}

/**
 * AnimatedList - A component that animates its children in sequence
 * with controlled timing and proper completion
 */
const AnimatedList: React.FC<AnimatedListProps> = ({
  children,
  className = '',
  staggerDelay = 250,
  randomVariation = 100,
  onComplete,
  component = 'ul'
}) => {
  const controls = useAnimation();
  const hasAnimated = useRef(false);
  const items = Children.toArray(children).filter(child => isValidElement(child));

  useEffect(() => {
    // Reset animation state when component mounts
    hasAnimated.current = false;

    const animateSequence = async () => {
      if (hasAnimated.current) return;

      for (let i = 0; i < items.length; i++) {
        // Start animation for this item
        await controls.start((idx) => {
          if (idx === i) {
            return { 
              opacity: 1, 
              y: 0,
              transition: { duration: 0.2 }
            };
          }
          return {};
        });

        // Calculate delay before next item
        let nextDelay = staggerDelay;

        // Add randomness for more organic feel
        nextDelay += (Math.random() * randomVariation * 2 - randomVariation);

        // Add occasional longer pause to simulate thinking
        if (Math.random() > 0.8) {
          nextDelay += 200;
        }

        // If it's not the last item, wait before showing the next item
        if (i < items.length - 1) {
          await new Promise((resolve) => setTimeout(resolve, nextDelay));
        }
      }

      hasAnimated.current = true;

      // Call onComplete after a short delay to ensure all animations are visible
      setTimeout(() => {
        if (onComplete) {
          onComplete();
        }
      }, 100);
    };

    animateSequence();

    return () => {
      controls.stop();
    };
  }, [items, controls, staggerDelay, randomVariation, onComplete]);

  const animatedItems = items.map((child, index) => {
    if (!isValidElement(child)) return child;

    return (
      <motion.div
        key={`item-${index}`}
        custom={index}
        initial={{ opacity: 0, y: 10 }}
        animate={controls}
        style={{ 
          width: '100%', 
          marginBottom: '4px',
          display: 'flex',
          justifyContent: 'flex-start'
        }}
      >
        {child}
      </motion.div>
    );
  });

  // Render the appropriate container element
  const containerProps = {
    className: `animated-list ${className}`,
    style: { 
      margin: 0,
      padding: 0,
      listStyle: 'none',
      display: 'flex',
      flexDirection: 'column' as const,
      alignItems: 'flex-start',
      width: '100%'
    }
  };

  switch (component) {
    case 'ol':
      return <ol {...containerProps}>{animatedItems}</ol>;
    case 'div':
      return <div {...containerProps}>{animatedItems}</div>;
    case 'ul':
    default:
      return <ul {...containerProps}>{animatedItems}</ul>;
  }
};

export default AnimatedList;
